use std::fs
use std::env

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if !number {
        print(text)
        return n
    }
    let ends_nl = text.ends_with("\n")
    let total: int = text.split("\n").count() as int
    let mut i: int = 0
    for p in text.split("\n") {
        i += 1
        if i == total && ends_nl {
            break
        }
        n += 1
        println("${n:>6}\t${p}")
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" { number = true } else { files.push(a) }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 { std::process::exit(status) }
}

