use std::fs
use std::env

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if !number {
        print(text)
        return n
    }
    let mut parts: Vec<string> = []
    for p in text.split("\n") { parts.push(p) }
    let total: int = parts.len() as int
    let mut i: int = 0
    for p in parts {
        let last = i == total - 1
        if last && p == "" {
            break
        }
        n += 1
        println("${n:>6}\t${p}")
        i += 1
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
            continue
        }
